from pathlib import Path
import difflib,json,subprocess,textwrap
H=Path(__file__).resolve().parent
rel=Path('servo/components/style/properties/cascade.rs')
s=(H/'parent'/rel).read_text()
def replace(old,new,count=1):
 global s
 assert s.count(old)==count,(old[:100],s.count(old))
 s=s.replace(old,new)
replace('ComputedValue as ComputedPropertyValue, Name,','ComputedValue as ComputedPropertyValue, FontDependencyDemand, Name,')
replace('    ensured_prioritary: PrioritaryPropertyIdSet,','    ensured_prioritary: PrioritaryPropertyIdSet,\n    completed_prioritary: PrioritaryPropertyIdSet,\n    priority_completion_flags: Option<RuleCascadeFlags>,')
replace('            ensured_prioritary: PrioritaryPropertyIdSet::default(),','            ensured_prioritary: PrioritaryPropertyIdSet::default(),\n            completed_prioritary: PrioritaryPropertyIdSet::default(),\n            priority_completion_flags: None,',2)
replace('        self.apply_one_prioritary_property(context, decls, cache, id, attribute_tracker);\n    }\n\n    /// Cascade a given custom property declaration.','        self.apply_one_prioritary_property(context, decls, cache, id, attribute_tracker);\n        self.refresh_priority_completion(context);\n        if self.completed_prioritary.contains_all(deps)\n            && !priority_has_dynamic_declarations(decls, id)\n        {\n            self.completed_prioritary.insert(id);\n        }\n    }\n\n    /// Cascade a given custom property declaration.')
replace('    fn ensure_prioritary_property(', '    fn refresh_priority_completion(&mut self, context: &computed::Context) {\n        if self.priority_completion_flags != Some(context.included_cascade_flags) {\n            self.completed_prioritary = PrioritaryPropertyIdSet::default();\n            self.priority_completion_flags = Some(context.included_cascade_flags);\n        }\n    }\n\n    fn ensure_prioritary_property(')
replace('struct PreparedMetricDeclaration {',(H/'COMPLETION.rs').read_text()+'\n'+(H/'INVENTORY.rs').read_text()+'\nstruct PreparedMetricDeclaration {')
replace('    #[derive(Clone, Copy)]\n    enum PublicationDemand',textwrap.indent((H/'PROVIDER.rs').read_text(),'    ')+'\n    #[derive(Clone, Copy)]\n    enum PublicationDemand')
replace('FnMut(&VarType, &PrioritaryPropertyIdSet) -> PublicationDemand','FnMut(FontDependencyDemand, &PrioritaryPropertyIdSet, bool) -> PublicationDemand',2)
replace('                                    let prepared = prepare_custom_value(\n                                        name,\n                                        self.value.as_ref().unwrap(),','                                    if preparation_needs_font_inputs(self.value_non_custom_refs, context.computed_context.is_root_element()) {\n                                        context.import_priority_completion();\n                                        let demand = frame_font_demand(self.registered, self.value_non_custom_refs, context.computed_context.is_root_element());\n                                        if !matches!(publication_ready(demand, &context.priority_completion.complete, has_unprepared_font_inputs(context.decls)), PublicationDemand::Ready) {\n                                            return FrameStep::Pending(None);\n                                        }\n                                    }\n                                    let prepared = prepare_custom_value(\n                                        name,\n                                        self.value.as_ref().unwrap(),')
replace('                        match publication_ready(&self.var, &context.priority_completion.complete) {','                        context.import_priority_completion();\n                        let demand = frame_font_demand(self.registered, self.value_non_custom_refs, context.computed_context.is_root_element());\n                        match publication_ready(demand, &context.priority_completion.complete, has_unprepared_font_inputs(context.decls)) {')
replace('        fn pending_metric_action(&self)', '        fn import_priority_completion(&mut self) {\n            self.cascade.refresh_priority_completion(self.computed_context);\n            self.priority_completion.complete = self.cascade.completed_prioritary.clone();\n        }\n\n        fn pending_metric_action(&self)')
replace('                    if id == action.prerequisite {\n                        assert!(self.priority_completion.complete.contains(id));','                    self.cascade.completed_prioritary.insert(id);\n                    if id == action.prerequisite {\n                        assert!(self.priority_completion.complete.contains(id));')
old='            context.poll_root(\n                var,\n                references_from_non_custom_properties,\n                attr_tracker,\n                &mut |_, _| PublicationDemand::Ready,\n            )'
new='            loop {\n                let result = context.poll_root(\n                    var.clone(),\n                    references_from_non_custom_properties,\n                    attr_tracker,\n                    &mut font_publication_demand,\n                );\n                if !matches!(result, VisitResult::ComputationPending(_)) {\n                    break result;\n                }\n                let Some(action) = context.pending_metric_action() else {\n                    break result;\n                };\n                match context.perform_metric_action(&action, attr_tracker) {\n                    MetricActionProgress::Published(_) | MetricActionProgress::AlreadyComplete => {},\n                    _ => break result,\n                }\n            }'
replace(old,new)
replace('                                self.value_non_custom_refs\n                                    .remove(ReferenceFlags::COLOR_SCHEME);\n','')
replace('                                    let prepared = prepare_custom_value(\n                                        name,\n                                        self.value.as_ref().unwrap(),','                                    self.value_non_custom_refs.remove(ReferenceFlags::COLOR_SCHEME);\n                                    let prepared = prepare_custom_value(\n                                        name,\n                                        self.value.as_ref().unwrap(),')
replace('                                    self.prepared_custom = Some(prepared);\n                                }\n','                                    self.prepared_custom = Some(prepared);\n                                } else {\n                                    self.value_non_custom_refs.remove(ReferenceFlags::COLOR_SCHEME);\n                                }\n')
q=H/'candidate'/rel;q.parent.mkdir(parents=True,exist_ok=True);q.write_text(s)
t=json.loads((H/'TOOLCHAIN.json').read_bytes())
paths=[rel,Path('servo/components/style/custom_properties.rs')]
subprocess.run([t['rustfmt'],'--config-path',str(H.parents[1]/t['config']),*[str(H/'candidate'/r) for r in paths]],check=True)
for name,folder in [('PARENT-DELTA.patch','parent'),('native.patch','base')]:
 (H/name).write_text(''.join(''.join(difflib.unified_diff((H/folder/r).read_text().splitlines(True),(H/'candidate'/r).read_text().splitlines(True),fromfile='a/'+str(r),tofile='b/'+str(r))) for r in paths))
